def create_statement_scores(apps, schema_editor):
    CompetencyScore = apps.get_model('app', 'AppraisalCompetencyScore')
    StatementScore = apps.get_model('app', 'AppraisalCompetencyStatementScore')
    database = schema_editor.connection.alias

    for competency_score in CompetencyScore.objects.using(database).select_related(
        'competency',
    ).iterator():
        statements = [
            item.strip().lstrip('-* ').strip()
            for item in competency_score.competency.description.splitlines()
            if item.strip()
        ]
        StatementScore.objects.using(database).bulk_create([
            StatementScore(
                competency_score_id=competency_score.pk,
                statement_index=index,
                statement=statement,
                end_year_score=competency_score.end_year_score,
            )
            for index, statement in enumerate(statements)
        ])


